  async function launchSelectedMission(){if(apiBusy)return;const route=selectedRoute||Engine.getSuggestedMission(s),base=JSON.parse(JSON.stringify(s));pendingMissionLaunch={base,missionId:route};s=Engine.createNextState(base,route);render();$('campaign-map').classList.remove('open');$('emergency').classList.remove('open');$('briefing').classList.add('open');updateStartLabel();showToast(`${Engine.getMission(route).title} READY · REVIEW BRIEFING BEFORE LAUNCH`)}
